・addチェックサム
u8 AddChkSum(u8* data, u32 len)
{
	u8 ret = 0;

	for(u32 i=0; i<len; i++)
	{
		ret += data[i];
	}

	return ret;
}
・xorチェックサム
u8 XorChkSum(u8* data, u32 len)
{
	u8 ret = 0;

	for(u32 i=0; i<len; i++)
	{
		ret ^= data[i];
	}

	return ret;
}
・Fletcher16
u16 Fletcher16(u8* data, u32 len)
{
	u16 sum1 = 0;
	u16 sum2 = 0;

	for(u32 i=0; i<len; i++)
	{
		sum1 = (sum1 + data[i]) % 255;
		sum2 = (sum2 + sum1) % 255;
	}

	return (sum2 << 8) | sum1;
}
・Adler32
・FNV1a 32bit
u32_t Fnv1a32(u8* data, u32 len)
{
	u32 hash = 2166136261u;	// FNV offset basis

	for(u32 i=0; i<len; i++)
	{
		hash ^= data[i];
		hash *= 16777619u;	// FNV prime
	}

	return hash;
}
・CRC32
u32 Crc32(u8* data, u32 len)
{

	u32 crc = 0xFFFFFFFF;

	for(u32 i=0; i<len; i++)
	{
		crc ^= data[i];

		// 1バイト(8ビット)ごとに多項式除算を行う
		for(u32 j=0; j<8; j++)
		{
			if(crc & 1)
			{
				crc = (crc >> 1) ^ 0xEDB88320; // マジックナンバー(生成多項式)
			}
			else
			{
				crc >>= 1;
			}
		}
	}

	return ~crc;
}

