サーボモーターを二つ付けていますが個別に制御しておらず、配線を分岐させているだけです。
プログラムはこんな感じ。
#include <Servo.h>

Servo servo1;

const int sensorPin = A5;

void setup() {
  servo1.attach(9);   // 1つ目のサーボ
}

void loop() {
  int val = analogRead(sensorPin);

  // 310〜410を30〜130度にマッピング
  int angle = map(val, 310, 410, 30, 130);

  // 範囲外の暴走防止
  angle = constrain(angle, 30, 130);

  servo1.write(angle);

  delay(20);
}

